create schema auth;create schema private;
create function auth.uid() returns uuid language sql stable as $$select (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid$$;
create function private.totus_can(text,text) returns boolean language sql stable as $$select coalesce((nullif(current_setting('request.jwt.claims',true),'')::jsonb->>$2)::boolean,false)$$;
grant usage on schema public,auth,private to authenticated;
grant execute on all functions in schema auth,private to authenticated;
create table public.products(id uuid default gen_random_uuid() not null primary key,family_id uuid,sku text not null,name text not null,product_type text default 'simple'::text not null,status text default 'PENDIENTE'::text not null,current_pvp numeric,proposed_pvp numeric,quick_competitor numeric,quick_discount numeric default 0 not null,units_month integer default 0 not null,notes text default ''::text not null,created_by uuid,created_at timestamptz default now() not null,updated_at timestamptz default now() not null);
create table public.product_variants(id uuid default gen_random_uuid() not null primary key,product_id uuid not null,sku text not null,name text not null,attributes jsonb default '{}'::jsonb not null,nicotine_mg_ml numeric,volume_ml numeric,special_tax_rate_ml numeric,special_tax_amount numeric,cost_net numeric,pvp numeric,active boolean default true not null,created_at timestamptz default now() not null);
create table public.product_provider_prices(id uuid default gen_random_uuid() not null primary key,product_id uuid not null,variant_id uuid,provider_id uuid not null,net_cost numeric default 0 not null,provider_discount numeric default 0 not null,shipping_unit numeric default 0 not null,moq integer default 0 not null,stock_status text default ''::text not null,price_date date,notes text default ''::text not null,selected boolean default false not null,created_at timestamptz default now() not null,purchase_origin text default 'España'::text not null,apply_special_tax boolean default false not null,special_tax_amount numeric default 0 not null);
create table public.product_competitor_prices(id uuid default gen_random_uuid() not null primary key,product_id uuid not null,variant_id uuid,competitor_name text not null,url text default ''::text not null,price numeric default 0 not null,discount numeric default 0 not null,shipping numeric default 0 not null,stock_status text default 'Sí'::text not null,promo_type text default ''::text not null,capture_date date,notes text default ''::text not null,created_at timestamptz default now() not null);
create table public.price_history(id uuid default gen_random_uuid() not null primary key,product_id uuid not null,variant_id uuid,user_id uuid,snapshot jsonb default '{}'::jsonb not null,created_at timestamptz default now() not null);
alter table public.product_variants add foreign key(product_id) references public.products(id);
alter table public.price_history add foreign key(product_id) references public.products(id);
grant select,insert,update,delete on all tables in schema public to authenticated;
alter table public.products enable row level security;
create policy team_all on public.products for all to authenticated using (auth.uid() is not null) with check(auth.uid() is not null);
create policy permission_create on public.products as restrictive for insert to authenticated with check(private.totus_can('pricing','create'));
create policy permission_edit on public.products as restrictive for update to authenticated using(private.totus_can('pricing','edit')) with check(private.totus_can('pricing','edit'));
alter table public.product_variants enable row level security;
create policy team_all on public.product_variants for all to authenticated using (auth.uid() is not null) with check(auth.uid() is not null);
create policy permission_create on public.product_variants as restrictive for insert to authenticated with check(private.totus_can('pricing','create'));
create policy permission_edit on public.product_variants as restrictive for update to authenticated using(private.totus_can('pricing','edit')) with check(private.totus_can('pricing','edit'));
alter table public.product_provider_prices enable row level security;
create policy team_all on public.product_provider_prices for all to authenticated using (auth.uid() is not null) with check(auth.uid() is not null);
create policy permission_create on public.product_provider_prices as restrictive for insert to authenticated with check(private.totus_can('pricing','create'));
create policy permission_edit on public.product_provider_prices as restrictive for update to authenticated using(private.totus_can('pricing','edit')) with check(private.totus_can('pricing','edit'));
alter table public.product_competitor_prices enable row level security;
create policy team_all on public.product_competitor_prices for all to authenticated using (auth.uid() is not null) with check(auth.uid() is not null);
create policy permission_create on public.product_competitor_prices as restrictive for insert to authenticated with check(private.totus_can('pricing','create'));
create policy permission_edit on public.product_competitor_prices as restrictive for update to authenticated using(private.totus_can('pricing','edit')) with check(private.totus_can('pricing','edit'));
alter table public.price_history enable row level security;
create policy team_all on public.price_history for all to authenticated using (auth.uid() is not null) with check(auth.uid() is not null);
create policy permission_create on public.price_history as restrictive for insert to authenticated with check(private.totus_can('pricing','create'));
create policy permission_edit on public.price_history as restrictive for update to authenticated using(private.totus_can('pricing','edit')) with check(private.totus_can('pricing','edit'));
drop policy permission_create on public.price_history;create policy totus_history_create on public.price_history as restrictive for insert to authenticated with check(private.totus_can('pricing','create'));
